const GUIDEBOOKS=[
 {id:'campaign',title:W('Search campaign: poora setup plan','Search campaign: a full setup plan'),intro:W('Har setting ka maqsad samjho, phir apna draft banao.','Understand each setting, then build your draft.'),source:'setup',steps:[
 [W('Business result likho','Write the business outcome'),W('Account mein campaign bananay se pehle decide karo: kis customer se kaunsa meaningful action chahiye? Local service ke liye qualified booking, shop ke liye completed purchase, B2B ke liye qualified opportunity socho.','Before creating a campaign, decide whose meaningful action you want. Consider qualified bookings for local service, completed purchases for a shop and qualified opportunities for B2B.'),W('Ek sentence: hum ___ ko ___ offer karke ___ result chahte hain.','One sentence: we offer ___ to ___ and want ___ as the outcome.')],
 [W('Measurement pehle test karo','Test measurement first'),W('Primary conversion aur selected campaign goal review karo. Success event ko backend/CRM se compare karo. Button click ko sale ya qualified lead assume mat karo.','Review the primary conversion and selected campaign goal. Compare the success event with the backend/CRM. A click is not automatically a sale or qualified lead.'),W('Ek valid, ek invalid aur ek repeated outcome ka test record.','A test record for one valid, one invalid and one repeated outcome.')],
 [W('Search type aur delivery options','Search type and delivery options'),W('Creation flow mein apna objective aur Search campaign type choose karo. Goal options account ke hisaab se vary ho saktay hain. Search partners aur kisi additional network option ko khud inspect karo; defaults ko bina parhay accept mat karo.','Choose the objective and Search campaign type in the creation flow. Goal options can vary by account. Inspect Search partners and any additional network options rather than accepting unread defaults.'),W('Network choice aur uski reason draft mein record.','Record the network choice and its reason in the draft.')],
 [W('Location aur language','Location and language'),W('Service coverage likho, phir included/excluded areas aur Presence vs Presence or interest ka option review karo. Physical local service aur overseas buyers ka context alag ho sakta hai. Ad/page ki language aur support capability align karo.','Define coverage, then review included/excluded areas and Presence versus Presence or interest. Local physical service and overseas buyers may need different choices. Align ad/page language with support capability.'),W('Coverage, exclusions, location option aur supported languages.','Coverage, exclusions, location option and supported languages.')],
 [W('Schedule, audience aur capacity','Schedule, audience and capacity'),W('Account timezone check karo. Calls kab answer hoti hain aur forms kab accept hotay hain? Audience Observation monitoring ke liye hota hai; Targeting reach narrow karta hai. Device-wise page test karo; bid adjustments ka behavior bidding strategy par depend karta hai.','Check the account timezone. When are calls answered and forms accepted? Observation monitors an audience; Targeting narrows reach. Test pages by device; bid-adjustment behavior depends on bidding strategy.'),W('Operating hours, timezone, audience mode aur mobile test result.','Operating hours, timezone, audience mode and a mobile test result.')],
 [W('Related keywords aur ad group','Related keywords and ad group'),W('Ek clear service/product intent choose karo. Keyword Planner se ideas lo, match type decide karo, phir negatives aur possible conflicts review karo. Same words ka matlab same need nahi hota.','Choose a clear service/product intent. Use Keyword Planner ideas, choose match types, then review negatives and conflicts. Shared words do not imply shared intent.'),W('Focused keyword list, negative plan aur destination page.','A focused keyword list, negative plan and destination page.')],
 [W('Ad, assets aur page promise','Ad, assets and the page promise'),W('RSA ke headlines/descriptions mein real offer, relevant benefit aur next step likho. Sitelinks/call/location assets relevant hon. Har combination truthful ho; page par same promise deliver ho.','Write the real offer, relevant benefit and next step in RSA headlines/descriptions. Use relevant sitelink/call/location assets. Every combination should be truthful and supported by the page.'),W('Ad builder ka saved draft aur mobile landing-page check.','A saved ad draft and a mobile landing-page check.')],
 [W('Budget, bidding aur AI controls','Budget, bidding and AI controls'),W('Affordable average daily budget aur possible monthly exposure dekho. Bidding business goal aur reliable conversion/value data ke mutabiq choose karo. AI Max on karna ho to search matching, text customization, final URL expansion aur exclusions review karo.','Check an affordable average daily budget and possible monthly exposure. Match bidding to business goals and reliable conversion/value data. If using AI Max, review search matching, text customization, final URL expansion and exclusions.'),W('Budget assumption, bidding reason aur automation controls ka plan.','Budget assumptions, bidding rationale and automation-control plan.')],
 [W('Review → controlled launch → monitoring','Review → controlled launch → monitoring'),W('Billing, verification, dates, policies, consent aur live measurement verify karo. Is app mein draft review simulated hai. Actual account mein launch ke baad delivery, spend, query relevance aur sales handoff monitor karo.','Verify billing, verification, dates, policies, consent and live measurement. Draft review here is simulated. After a real launch, monitor delivery, spend, query relevance and the sales handoff.'),W('Business-specific launch checklist aur first review date.','A business-specific launch checklist and first review date.')]
 ]},
 {id:'gtm',title:W('GTM tracking: implementation workbook','GTM tracking: implementation workbook'),intro:W('Manual website conversion ke setup aur testing ka guided plan.','A guided plan for a manual website conversion and testing.'),source:'tagsetup',steps:[
 [W('Ek clear outcome choose karo','Choose one clear outcome'),W('Success ka exact meaning define karo: server-confirmed form, valid booking ya purchase. Conversion source, counting rule, value/currency aur goal alignment decide karo. Isi outcome ko dusray primary source se duplicate count na karo.','Define success precisely: a server-confirmed form, valid booking or purchase. Decide the source, counting rule, value/currency and goal alignment. Avoid duplicate primary measurement of the same outcome.'),W('Measurement sheet: outcome, source, owner, value aur selected goal.','Measurement sheet: outcome, source, owner, value and selected goal.')],
 [W('Existing tags ka inventory lo','Inventory existing tags'),W('Website/CMS mein Google tag aur GTM pehle se installed hain ya nahi, inspect karo. Existing Ads/Analytics destinations aur hardcoded tags ko identify karo. Same base setup ko blindly dobara install mat karo.','Inspect whether the Google tag and GTM are already installed through the site/CMS. Identify existing Ads/Analytics destinations and hardcoded tags. Avoid blindly reinstalling the same base setup.'),W('Existing tag IDs, container aur deployment owner ki list. Passwords nahi.','A list of existing tag IDs, container and deployment owner. No passwords.')],
 [W('Manual conversion ki setup details lo','Get manual conversion setup details'),W('Google Ads ke current conversion setup mein website/manual route aur GTM instructions review karo. Manual Ads conversion tag ko Conversion ID aur Conversion Label chahiye. Auto-detected actions ka route different ho sakta hai.','Review current website/manual conversion setup and GTM instructions in Google Ads. A manual Ads conversion tag needs a Conversion ID and Conversion Label. Auto-detected actions can use a different route.'),W('Correct account/action ki ID-label mapping; sensitive customer data ke baghair.','Correct account/action ID-label mapping, without sensitive customer data.')],
 [W('Success signal design karo','Design the success signal'),W('Developer ke saath decide karo confirmed outcome ka reliable event kaise milega. Purchase mein actual value, currency aur unique transaction ID validate karo. URL-only success pages mein refresh/direct visit edge cases test karo.','Work with the developer on a reliable confirmed-outcome signal. Validate actual value, currency and a unique transaction ID for purchases. Test refresh/direct-visit edge cases on URL-only success pages.'),W('Success event contract aur valid/invalid/repeat test cases.','A success-event contract and valid/invalid/repeat test cases.')],
 [W('Tag, variables aur trigger configure karo','Configure tag, variables and trigger'),W('GTM ke Google Ads Conversion Tracking tag mein manual ID/label aur needed variables map karo. Trigger ko selected outcome ke saath match karo. Google tag/Conversion Linker ke current instructions aur domain setup review karo.','Map the manual ID/label and required variables in a GTM Google Ads Conversion Tracking tag. Match the trigger to the intended outcome. Review current Google tag/Conversion Linker guidance and domain setup.'),W('Tag configuration, trigger reason aur payload mapping ki reviewed copy.','A reviewed tag configuration, trigger rationale and payload mapping.')],
 [W('Consent aur privacy review','Review consent and privacy'),W('Applicable consent requirements aur Google policies ke mutabiq collection setup karo. Consent Mode choice ko communicate karta hai; user se consent lenay ka replacement nahi. Sirf hash karna data use ki permission nahi banata.','Configure collection around applicable consent requirements and Google policies. Consent Mode communicates choices; it does not replace obtaining consent. Hashing alone does not authorize data use.'),W('Relevant consent states ka test plan aur approved data-handling process.','A test plan for relevant consent states and an approved data-handling process.')],
 [W('Preview mein end-to-end test','Test end to end in Preview'),W('GTM Preview/Tag Assistant se valid outcome complete karo. Trigger count, conversion destination, value/currency aur duplicate cases inspect karo. Backend/CRM mein same outcome confirm karo. Fired tag aur attributed Ads conversion report ko same proof mat samjho.','Complete a valid outcome using GTM Preview/Tag Assistant. Inspect trigger count, destination, value/currency and duplicate cases. Confirm the same outcome in the backend/CRM. A fired tag is not the same proof as an attributed Ads conversion report.'),W('Valid/invalid/repeat tests ka pass/fail log aur observed payload.','A pass/fail log for valid/invalid/repeat tests and observed payloads.')],
 [W('Publish, monitor aur reconcile','Publish, monitor and reconcile'),W('Reviewed container changes ko publish karo, version note aur rollback plan rakho. Phir actual site par retest, Ads status/diagnostics aur reporting delay review karo. Bina evidence baar baar naye tags mat add karo.','Publish reviewed container changes with version notes and a rollback plan. Retest the live site, review Ads status/diagnostics and allow for reporting delay. Avoid repeatedly adding tags without evidence.'),W('Published version, owner, live retest aur next reconciliation date.','Published version, owner, live retest and next reconciliation date.')]
 ]},
 {id:'review',title:W('Weekly optimization: evidence se action','Weekly optimization: evidence to action'),intro:W('Bina random edits ke ek useful review complete karo.','Complete a useful review without random edits.'),source:'terms',steps:[
 [W('Same date range aur mature data','Comparable dates and mature data'),W('Comparison ka date range, business goal aur conversion delay note karo. Recent incomplete sales ko mature period se unfairly compare mat karo.','Record date range, business goal and conversion delay. Avoid unfair comparisons between incomplete recent sales and mature periods.'),W('Review dates, selected conversion goals aur lag assumption.','Review dates, selected conversion goals and lag assumptions.')],
 [W('Measurement aur sales reconcile','Reconcile measurement and sales'),W('Ads conversions ko backend/CRM outcomes se compare karo. Duplicate tags, source changes, spam ya sales follow-up gaps inspect karo. Attribution differences ko actual missing sales se alag investigate karo.','Compare Ads conversions with backend/CRM outcomes. Inspect duplicate tags, source changes, spam and sales follow-up gaps. Investigate attribution differences separately from missing sales.'),W('Mismatch list: evidence, likely cause aur next verification.','A mismatch list: evidence, likely cause and next verification.')],
 [W('Search intent aur coverage','Search intent and coverage'),W('Visible search terms ko relevant, irrelevant aur uncertain mein group karo. Privacy thresholds ki wajah se report complete query log nahi. Negatives add karte waqt scope aur useful traffic par asar review karo.','Group visible search terms as relevant, irrelevant and uncertain. Privacy thresholds mean this is not a complete query log. Review negative scope and impact on useful traffic.'),W('Proposed negatives aur retained/uncertain terms ki reasons.','Reasons for proposed negatives and retained/uncertain terms.')],
 [W('Funnel ka weak point dhoondo','Find the funnel bottleneck'),W('CPC, click-to-lead CVR, qualification rate aur close rate alag dekho. High CPA ka reason expensive clicks, poor page/offer ya poor sales handling ho sakta hai. Sample size aur intent context zaroor dekho.','Inspect CPC, click-to-lead CVR, qualification rate and close rate separately. High CPA may reflect click costs, page/offer issues or sales handling. Account for sample size and intent.'),W('Ek prioritized bottleneck aur uski evidence.','One prioritized bottleneck and its evidence.')],
 [W('Ek focused change choose karo','Choose a focused change'),W('Hypothesis likho: agar hum ___ change karein to ___ metric improve honi chahiye kyun ke ___. Primary success metric, guardrail aur review window pehle decide karo.','Write a hypothesis: changing ___ should improve ___ because ___. Decide the main success metric, guardrail and review window first.'),W('Change log: hypothesis, owner, date aur validation plan.','Change log: hypothesis, owner, date and validation plan.')],
 [W('Profitability ke baad scaling','Scale after checking profitability'),W('Revenue ROAS ke saath contribution margin, returns, lead quality aur service capacity dekho. Extra spend ki efficiency historical average se different ho sakti hai.','Review contribution margin, returns, lead quality and capacity alongside revenue ROAS. Incremental spending efficiency may differ from historical averages.'),W('Weak/base/strong assumptions aur controlled budget decision.','Weak/base/strong assumptions and a controlled budget decision.')]
 ]}
];
let guideId='campaign',guideStep=0;
function guideKey(){return state.business+'/'+guideId;}
function guideChecks(){return state.guideChecks[guideKey()]||(state.guideChecks[guideKey()]=[]);}
function cleanGuideChecks(v){const result={};if(v&&typeof v==='object')for(const b of BUSINESSES)for(const g of GUIDEBOOKS){const key=b.id+'/'+g.id;if(Array.isArray(v[key]))result[key]=[...new Set(v[key].filter(i=>Number.isInteger(i)&&i>=0&&i<g.steps.length))];}return result;}
function checksForBusiness(){return state.businessChecks[state.business]||(state.businessChecks[state.business]=[]);}
function cleanBusinessChecks(v){const result={};if(v&&typeof v==='object')for(const b of BUSINESSES)if(Array.isArray(v[b.id]))result[b.id]=[...new Set(v[b.id].filter(i=>Number.isInteger(i)&&i>=0&&i<LAUNCH_CHECKS.length))];return result;}
function migrateBusinessChecks(){state.businessChecks=cleanBusinessChecks(state.businessChecks);if(!Object.keys(state.businessChecks).length&&Array.isArray(state.checks)&&state.checks.length)state.businessChecks[state.business]=state.checks.filter(i=>Number.isInteger(i)&&i>=0&&i<LAUNCH_CHECKS.length);state.checks=[];state.guideChecks=cleanGuideChecks(state.guideChecks);}
function guidesPage(){const g=GUIDEBOOKS.find(g=>g.id===guideId)||GUIDEBOOKS[0];guideStep=Math.max(0,Math.min(g.steps.length-1,guideStep));const s=g.steps[guideStep];return `${heading('FROM A LESSON TO A WORKING PLAN',U('Ek step. Ek clear result.','One step. One clear result.'),U('Implementation workbook: instructions parho, apna evidence verify karo, phir next step.','Implementation workbook: read instructions, verify your evidence, then continue.'))}<div class="section-heading"><span class="tag">${esc(t(biz().name))}</span><select id="guide-business" class="lang" aria-label="Guide business">${BUSINESSES.map(b=>`<option value="${b.id}" ${b.id===state.business?'selected':''}>${esc(t(b.name))}</option>`).join('')}</select></div><div class="tabs">${GUIDEBOOKS.map(x=>`<button data-guide="${x.id}" class="${guideId===x.id?'active':''}">${esc(t(x.title))}</button>`).join('')}</div><div class="guide-layout"><aside class="card"><h3>${esc(t(g.title))}</h3><p>${esc(t(g.intro))}</p>${g.steps.map((x,i)=>`<button data-guide-step="${i}" class="guide-step ${guideStep===i?'active':''}"><span>${guideChecks().includes(i)?'✓':String(i+1).padStart(2,'0')}</span>${esc(t(x[0]))}</button>`).join('')}</aside><article class="card"><div class="simulation-label">GUIDE · NOT A GOOGLE SCREENSHOT OR LIVE ACCOUNT CONTROL</div><div class="eyebrow" style="margin-top:20px">STEP ${guideStep+1} / ${g.steps.length}</div><h2>${esc(t(s[0]))}</h2><p class="guide-instruction">${esc(t(s[1]))}</p><div class="example"><div class="label">${U('IS STEP KA OUTPUT','OUTPUT FOR THIS STEP')}</div><p>${esc(t(s[2]))}</p></div><label class="sim-check"><input id="guide-done" type="checkbox" ${guideChecks().includes(guideStep)?'checked':''}>${U('Maine is step ka output khud verify kiya.','I have verified this step’s output myself.')}</label><p style="font-size:11px;color:var(--muted)">${U('Ye self-check hai. App tumhara real account, tag ya policy approval verify nahi karti.','This is a self-check. The app does not verify your real account, tags or policy approval.')}</p><div class="lesson-nav"><button class="btn light" id="guide-prev" ${!guideStep?'disabled':''}>← ${U('Pichla step','Previous step')}</button><button class="btn" id="guide-next" ${guideStep===g.steps.length-1?'disabled':''}>${U('Agla step','Next step')} →</button></div><div class="action-row"><button class="btn light" id="guide-practice">${U('Related practice kholo','Open related practice')}</button><button class="btn light" id="guide-export">${U('Workbook checklist export','Export workbook checklist')}</button></div><details class="source-details"><summary>${U('Official instructions aur source','Official instructions and source')}</summary>${sourceLinks([g.source])}${g.id==='gtm'?`<a class="source-link" href="https://support.google.com/tagmanager/answer/6105160?hl=en" target="_blank" rel="noopener noreferrer">↗ Google Ads conversion tag in GTM</a>${sourceLinks(['tagtest','consent'])}`:''}${g.id==='campaign'?sourceLinks(['geo','settings','bid','budget']):''}</details>${videoForGuide(g.id)}</article></div>${footer()}`;}
function bindGuides(){$('#guide-business').onchange=e=>{state.business=e.target.value;save();render();};$$('[data-guide]').forEach(b=>b.onclick=()=>{guideId=b.dataset.guide;guideStep=0;render();});$$('[data-guide-step]').forEach(b=>b.onclick=()=>{guideStep=+b.dataset.guideStep;render();});$('#guide-prev').onclick=()=>{guideStep=Math.max(0,guideStep-1);render();};$('#guide-next').onclick=()=>{const g=GUIDEBOOKS.find(g=>g.id===guideId);guideStep=Math.min(g.steps.length-1,guideStep+1);render();};$('#guide-done').onchange=e=>{const checks=guideChecks().filter(i=>i!==guideStep);if(e.target.checked)checks.push(guideStep);state.guideChecks[guideKey()]=checks;save();const y=window.scrollY;render();window.scrollTo(0,y);};$('#guide-practice').onclick=()=>{if(guideId==='gtm'){workshopTab='tracking';go('workshop');}else{labTab=guideId==='campaign'?'campaign':'diagnose';go('lab');}};$('#guide-export').onclick=()=>{const g=GUIDEBOOKS.find(g=>g.id===guideId);download('ads-asaan-'+state.business+'-'+guideId+'-workbook.json',{business:biz().name[1],guide:g.title[1],selfReported:true,items:g.steps.map((s,i)=>({step:i+1,title:s[0][1],expectedOutput:s[2][1],selfVerified:guideChecks().includes(i)})),exportedAt:new Date().toISOString()});};bindMedia();}
const CAMPAIGN_FIELDS=['name','goal','location','budget','bid','keywords','negatives','url','geo','exclusions','languages','networks','schedule','timezone','audience','audienceReason','measurement','target','ai','urlExpansion','urlExclusions'];
function campaignField(key,label,value,help='',type='text'){return `<label class="field">${esc(label)}<input id="campaign-${key}" type="${type}" value="${esc(value??'')}" maxlength="${key==='url'?2000:250}" ${type==='number'?'step="any" min="0"':''}>${help?`<small>${esc(help)}</small>`:''}</label>`;}
function campaignSelect(key,label,value,options,help=''){return `<label class="field">${esc(label)}<select id="campaign-${key}">${options.map(([v,name])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t(name))}</option>`).join('')}</select>${help?`<small>${esc(help)}</small>`:''}</label>`;}
function expandedCampaignLab(){const b=biz(),d=draft();return `<div class="cards"><section class="card"><div class="simulation-label">TEACHING WORKSPACE · NO REAL GOOGLE ADS CONNECTION</div><h2 style="margin-top:12px">${U('Campaign ka complete plan','A complete campaign plan')}</h2><p>${U('Changes is browser mein automatically save hotay hain. Har section khol kar reason samjho. Ye Google editor ki exact copy nahi.','Changes save automatically in this browser. Open each section to understand the choices. This is not an exact Google editor replica.')}</p><span class="tag" id="draft-save-status" role="status">${U('Browser-local draft','Browser-local draft')}</span><details class="campaign-section" open><summary>01 · ${U('Goal aur budget','Goal and budget')}</summary>${campaignField('name','Campaign name',d.name??b.name[1]+' | Search')}<div class="form-grid">${campaignSelect('goal','Primary outcome',d.goal??(state.business==='shop'?'purchase':'qualified'),[['qualified',W('Qualified lead / booking','Qualified lead / booking')],['purchase',W('Completed purchase','Completed purchase')],['pageview',W('Page view','Page view')]])}${campaignField('budget','Average daily budget (Rs)',d.budget??1000,U('Average hai; har din ka hard cap nahi.','An average, not a daily hard cap.'),'number')}${campaignSelect('bid','Bidding objective',d.bid??'Maximize conversions',['Maximize conversions','Target CPA','Maximize conversion value','Target ROAS','Maximize clicks','Manual CPC'].map(v=>[v,W(v,v)]))}${campaignField('target',U('Optional target: CPA (Rs) / ROAS (%)','Optional target: CPA (Rs) / ROAS (%)'),d.target??'',U('Target CPA/ROAS choose karo to target required hai. 300% ROAS = 3×.','A target is required for Target CPA/ROAS. 300% ROAS = 3×.'),'number')}</div></details><details class="campaign-section"><summary>02 · ${U('Kahan, kis ko, kab?','Where, who and when?')}</summary><div class="form-grid">${campaignField('location','Included locations',d.location??b.city)}${campaignSelect('geo','Location option',d.geo??'presence',[['presence',W('Presence — likely in/regularly in area','Presence — likely in/regularly in area')],['interest',W('Presence or interest','Presence or interest')]],U('Choice service model par depend karti hai; universal setting nahi.','Choose for the service model; there is no universal setting.'))}${campaignField('exclusions','Excluded locations (if needed)',d.exclusions??'')}${campaignField('languages','Supported ad/page languages',d.languages??'English, Urdu')}${campaignSelect('networks','Search network plan',d.networks??'google',[['google',W('Google Search; partners not included in plan','Google Search; partners not included in plan')],['partners',W('Google Search + Search partners test','Google Search + Search partners test')]])}${campaignField('schedule','Ad/service schedule',d.schedule??(state.business==='shop'?'All day; online orders accepted':'Mon–Sat, 09:00–18:00; confirm staffing'))}${campaignField('timezone','Account timezone to verify',d.timezone??'Asia/Karachi')}${campaignSelect('audience','Audience mode',d.audience??'observation',[['observation',W('Observation — monitor without narrowing reach','Observation — monitor without narrowing reach')],['targeting',W('Targeting — narrow reach to audience','Targeting — narrow reach to audience')]])}</div>${campaignField('audienceReason','Audience rationale / segment plan',d.audienceReason??'',U('Targeting choose karo to narrowing ki reason aur segment likho.','For Targeting, explain the segment and reason for narrowing.'))}</details><details class="campaign-section"><summary>03 · ${U('Keywords, ad aur page','Keywords, ad and page')}</summary><label class="field">Keywords · one per line<textarea id="campaign-keywords">${esc(d.keywords??'['+b.customer[1]+']\n"'+b.customer[1]+'"')}</textarea></label><label class="field">Negative keywords · one per line<textarea id="campaign-negatives">${esc(d.negatives??'jobs\ncourse')}</textarea></label>${campaignField('url','Landing page URL',d.url??'',U('Apni real business page. Demo .example URL usable destination nahi.','Use a real business page. A demo .example URL is not a usable destination.'),'url')}<p>${U('Ad text edit karne ke liye Ad builder tab kholo. Current draft automatically retain hoga.','Use the Ad builder tab to edit ad text. Your current draft will be retained automatically.')}</p></details><details class="campaign-section"><summary>04 · ${U('Measurement aur AI controls','Measurement and AI controls')}</summary>${campaignSelect('measurement','Tracking test status (self-reported)',d.measurement??'untested',[['untested',W('Abhi test nahi kiya','Not tested yet')],['verified',W('Valid/invalid/repeat tests reviewed','Valid/invalid/repeat tests reviewed')]])}${campaignSelect('ai','AI Max plan',d.ai??'off',[['off',W('Off for this plan','Off for this plan')],['on',W('On — review controls and outcomes','On — review controls and outcomes')]])}${campaignSelect('urlExpansion','Final URL expansion plan',d.urlExpansion??'off',[['off',W('Off','Off')],['on',W('On — review destinations and text customization','On — review destinations and text customization')]])}${campaignField('urlExclusions','URL exclusions / destination review plan',d.urlExclusions??'',U('Login, careers aur irrelevant pages ka plan likho.','Plan for login, careers and irrelevant pages.'))}<p>${U('AI Max aur URL expansion ki actual availability/dependencies account mein verify karo. Expansion on ho to RSA pinning ke rules bhi check karo.','Verify actual AI Max/URL expansion availability and dependencies in the account. Also check RSA pinning rules when expansion is enabled.')}</p></details><div class="action-row"><button class="btn" id="validate-campaign">${U('Plan review karo','Review my plan')}</button><button class="btn light" id="export-campaign">${U('Draft export','Export draft')}</button></div><div id="campaign-feedback" aria-live="polite"></div></section><aside><div class="card"><h3>${U('Is business ki launch checklist','This business’s launch checklist')}</h3><p>${U('AC, store aur B2B ki checks alag save hoti hain. Ye self-reported hain.','Checks save separately for AC, the store and B2B. They are self-reported.')}</p>${checklist()}<div class="action-row"><button class="btn light" id="simulate-launch">${U('Practice readiness check','Practice readiness check')}</button></div><div id="launch-feedback" aria-live="polite"></div></div><div class="card" style="margin-top:20px"><h3>${U('Setup ka step-by-step guide','Step-by-step setup guide')}</h3><p>${U('Har setting ko ek step mein samjho aur expected output verify karo.','Understand each setting and verify the expected output.')}</p><button class="btn light" data-go="guides">${U('Workbook kholo','Open workbook')}</button></div></aside></div>`;}
function readCampaignDraft(){const d={...draft()};for(const field of CAMPAIGN_FIELDS){const el=$('#campaign-'+field);if(el)d[field]=el.value.trim();}d.validated=false;state.drafts[state.business]=d;save();return d;}
function reviewCampaignPlan(d){const issues=[],notes=[];const issue=(ur,en)=>issues.push(W(ur,en));if(!d.name?.trim())issue('Campaign name dalo.','Enter a campaign name.');if(!d.location?.trim())issue('Included location dalo.','Enter an included location.');if(!Number.isFinite(Number(d.budget))||Number(d.budget)<=0||Number(d.budget)>10000000)issue('Valid positive budget dalo.','Enter a valid positive budget.');if(!d.keywords?.trim())issue('Relevant keyword plan add karo.','Add a relevant keyword plan.');if(!['qualified','purchase'].includes(d.goal))issue('Is sales exercise mein purchase ya qualified lead choose karo.','Choose a purchase or qualified lead for this sales exercise.');try{const u=new URL(d.url);if(!['https:','http:'].includes(u.protocol)||u.hostname.endsWith('.example')||!u.hostname.includes('.'))throw Error();}catch{issue('Real landing-page URL dalo.','Enter a real landing-page URL.');}if(!d.adSaved)issue('Ad builder mein completed ad draft save karo.','Save a completed ad in the ad builder.');if(['Target CPA','Target ROAS'].includes(d.bid)&&(!Number.isFinite(Number(d.target))||Number(d.target)<=0))issue('Selected strategy ke liye positive target dalo.','Enter a positive target for the selected strategy.');if(!d.languages?.trim()||!d.schedule?.trim())issue('Supported languages aur schedule record karo.','Record supported languages and schedule.');try{new Intl.DateTimeFormat('en',{timeZone:d.timezone}).format();if(!d.timezone)throw Error();}catch{issue('Valid account timezone verify karo.','Verify a valid account timezone.');}if(d.audience==='targeting'&&!d.audienceReason?.trim())issue('Audience Targeting ki reason aur segment likho.','Describe the audience segment and rationale for Targeting.');if(d.measurement!=='verified')issue('Valid/invalid/repeat tracking tests pehle review karo.','Review valid/invalid/repeat tracking tests first.');if(d.urlExpansion==='on'&&(d.ai!=='on'||!d.urlExclusions?.trim()))issue('Is practice plan mein URL expansion ke liye AI controls aur destination exclusions ka plan complete karo.','For this practice plan, complete AI controls and the destination-exclusion plan for URL expansion.');if(!d.negatives?.trim())notes.push(W('Negative plan abhi khali hai. Actual queries aur possible conflicts review karo.','The negative plan is empty. Review actual queries and possible conflicts.'));if(d.geo==='interest')notes.push(W('Presence or interest ko service coverage ke saath validate karo.','Validate Presence or interest against service coverage.'));if(d.bid==='Target ROAS'||d.bid==='Maximize conversion value')notes.push(W('Value-based bidding ke liye actual conversion values/currency validate karo.','Validate actual conversion values/currency for value-based bidding.'));return{issues,notes};}
function expandedValidateCampaign(){const d=readCampaignDraft(),r=reviewCampaignPlan(d);state.drafts[state.business].validated=!r.issues.length;save();$('#campaign-feedback').innerHTML=`<div class="feedback ${r.issues.length?'error':''}" style="margin-top:18px"><b>${r.issues.length?U('Plan mein ye cheezen review karo:','Review these items:'):U('Practice plan ke basic checks pass.','Basic practice-plan checks passed.')}</b>${r.issues.map(i=>`<p style="margin:7px 0">• ${esc(t(i))}</p>`).join('')}${r.notes.map(i=>`<p style="margin:7px 0">↳ ${esc(t(i))}</p>`).join('')}<p style="font-size:11px">${U('Ye actual account settings, tag firing, URL availability, policy approval ya results verify nahi karta.','This does not verify actual account settings, tag firing, URL availability, policy approval or results.')}</p></div>`;return !r.issues.length;}
function bindDraftAutosave(){if(labTab==='campaign')for(const key of CAMPAIGN_FIELDS){const el=$('#campaign-'+key);if(el)el.addEventListener('input',()=>{readCampaignDraft();const status=$('#draft-save-status');if(status)status.textContent=storageOK?U('Draft is browser mein save ho gaya','Draft saved in this browser'):U('Save nahi hua — storage unavailable','Not saved — storage unavailable');});}if(labTab==='ad')$$('[data-ad]').forEach(el=>el.addEventListener('input',()=>{const values=Object.fromEntries($$('[data-ad]').map(i=>[i.dataset.ad,i.value]));state.drafts[state.business]={...draft(),...values,adSaved:false,validated:false};save();}));}
