function officialVideoCard(v){return `<article class="resource"><div class="media-placeholder" data-video-holder="${v.id}"><div style="margin-bottom:12px">${icon('play',32)}</div><button class="btn" data-video="${v.id}">${U('Official video load karo','Load official video')}</button><p>${U('Play par YouTube third-party content load hoga.','Playing loads third-party content from YouTube.')}</p></div><div class="body"><span class="tag">OFFICIAL GOOGLE VIDEO · ENGLISH</span><h3 style="margin-top:12px">${esc(v.title)}</h3><small class="video-source-note">Official Google source · checked 20 Oct 2026</small>${sourceLinks([v.source])}<a class="source-link" href="https://www.youtube.com/watch?v=${v.id}" target="_blank" rel="noopener noreferrer">${U('YouTube par kholo','Open on YouTube')} ↗</a><button class="text-btn" data-go="lesson/${v.lesson}">${U('Related lesson kholo','Open related lesson')} →</button></div></article>`;}
function videoForGuide(id){const v=OFFICIAL_VIDEOS.find(v=>v.topic===(id==='gtm'?'tracking':'ads'));return id==='review'?'':`<div style="margin-top:25px">${officialVideoCard(v)}</div>`;}
function lessonVideoLink(l){const v=OFFICIAL_VIDEOS.find(v=>v.lesson===l.id);return v?`<details class="source-details"><summary>${U('Is topic ka official video dekho','Watch an official video for this topic')}</summary>${officialVideoCard(v)}</details>`:'';}
